// 最小 axios 兼容垫片：只实现本项目用到的子集（requestJson 的调用方式）。
// 基于 Node 18+ 全局 fetch，无第三方依赖。
module.exports = async function axios(config) {
  const { url, method = 'GET', headers = {}, data, timeout, signal } = config || {};
  const ctrl = new AbortController();
  const timers = [];
  let timedOut = false;
  if (signal) {
    if (signal.aborted) {
      const e = new Error('request canceled');
      e.code = 'ERR_CANCELED';
      throw e;
    }
    signal.addEventListener('abort', () => ctrl.abort(), { once: true });
  }
  if (timeout && timeout > 0) {
    timers.push(setTimeout(() => { timedOut = true; ctrl.abort(); }, timeout));
  }
  let res;
  try {
    res = await fetch(url, { method, headers, body: data, signal: ctrl.signal, redirect: 'manual' });
  } catch (e) {
    const err = new Error(timedOut ? 'timeout' : 'network error');
    err.code = timedOut ? 'ETIMEDOUT' : 'ERR_NETWORK';
    throw err;
  } finally {
    timers.forEach(clearTimeout);
  }
  const text = await res.text();
  const h = {};
  res.headers.forEach((v, k) => { h[String(k).toLowerCase()] = v; });
  return { status: res.status, headers: h, data: text };
};
